    def isHappy(self, n: int) -> bool:
        def get_next(val):
            total = 0
            while val > 0:
                d = val % 10
                total += d * d
                val //= 10
            return total
        slow = n
        fast = get_next(n)
        while fast != 1 and slow != fast:
            slow = get_next(slow)
            fast = get_next(get_next(fast))
        return fast == 1

