var isHappy = function(n) {
    function getNext(val) {
        let total = 0;
        while (val > 0) {
            const d = val % 10;
            total += d * d;
            val = Math.floor(val / 10);
        }
        return total;
    }
    let slow = n;
    let fast = getNext(n);
    while (fast !== 1 && slow !== fast) {
        slow = getNext(slow);
        fast = getNext(getNext(fast));
    }
    return fast === 1;
};
